-- CAB-0012: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='amanah' and type='party') then raise exception 'CAB-0012: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='government' and type='bloc') then raise exception 'CAB-0012: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('dzulkefly-ahmad','amir-hamzah-azizan') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0012: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kuala selangor') and slug not in ('dzulkefly-ahmad','amir-hamzah-azizan')) then raise exception 'CAB-0012: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0012:%' and (m.source_type <> 'editorial' or e.slug not in ('dzulkefly-ahmad','amir-hamzah-azizan') or m.import_key not like 'CAB-0012:' || e.slug || ':%')) then raise exception 'CAB-0012: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'dzulkefly-ahmad','Dzulkefly Ahmad','government','Minister of Health','Kuala Selangor','Selangor','Dzulkefly Ahmad is Minister of Health. He represents Kuala Selangor, Selangor, in the Dewan Rakyat. He is a member of Parti Amanah Negara (AMANAH).','https://www.moh.gov.my/','/portraits/dzulkefly-ahmad.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P096.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Kuala Selangor", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4135"}, {"label": "AMANAH · Dzulkefly Ahmad (July 2026)", "url": "https://www.bernama.com/en/news.php?id=2588546"}]'::jsonb from public.entities parent where parent.slug='amanah' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'amir-hamzah-azizan','Amir Hamzah Azizan','government','Minister of Finance II',null,null,'Amir Hamzah Azizan is Minister of Finance II. He serves as a senator appointed by the Yang di-Pertuan Agong.','https://www.mof.gov.my/','/portraits/amir-hamzah-azizan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2023/MK2.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Dewan Negara", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dn&id=4289"}]'::jsonb from public.entities parent where parent.slug='government' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('dzulkefly-ahmad','amir-hamzah-azizan') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0012: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0012:dzulkefly-ahmad:emr-national-2029','Equip all public hospitals and primary health facilities with EMR by 2029','Health','in_progress',null,'2029-12-31','2025-11-15','https://www.bernama.com/en/general/news.php?id=2491200','2026-08-31','https://bernama.com/en/general/news.php?id=2601235','Dzulkefly set a 2029 target covering 150 public hospitals and more than 3,000 primary health facilities through hospital and clinic digital-record systems.','The initial statement records existing clinic deployment. His August 2026 update describes accelerated expansion supported by additional funding. Funding is not proof of universal coverage; no comparable completed-facility total for the entire hospital-and-clinic scope was verified.','2026-11-09','editorial',false from public.entities e where e.slug='dzulkefly-ahmad' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0012:amir-hamzah-azizan:fiscal-deficit-below-3','Reduce the fiscal deficit below 3% of GDP within two years','Economy','in_progress',null,null,'2026-10-13','https://web26.bernama.com/en/region/news.php?id=2619840','2026-10-13','https://web26.bernama.com/en/region/news.php?id=2619840','Amir Hamzah said Malaysia aimed to reduce its fiscal deficit below 3% of GDP within two years through fiscal consolidation and subsidy reforms.','The October statement reports a 3.7% deficit for 2025 and continuing reforms. That GDP ratio is not a completion score. A result for the two-year horizon was not established; no exact day is imposed on the stated horizon.','2026-11-09','editorial',false from public.entities e where e.slug='amir-hamzah-azizan' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

